"""Parse and format page-range strings like "1-5,8,11-13"."""


class RangeError(ValueError):
    def __init__(self, message, pos):
        self.pos = pos
        super().__init__(f"{message} (at character position {pos})")


def _parse_int(token, pos):
    if not token.isdigit():
        raise RangeError(f"invalid page number {token!r}", pos)
    n = int(token)
    if n <= 0:
        raise RangeError(f"page numbers must be positive, got {n}", pos)
    return n


def parse(s):
    """Parse a page-range string into a sorted list of unique positive ints.

    Accepts single pages ("8"), ranges ("11-13"), separated by commas,
    with optional whitespace around items.
    """
    pages = set()
    for item in s.split(","):
        pos = len(s) - len(s.lstrip()) + 0  # placeholder, computed below
        pos = s.find(item) if item else -1
        stripped = item.strip()
        if not stripped:
            # find actual offset of the empty/bad item
            start = sum(len(p) + 1 for p in s.split(",")[: s.split(",").index(item)])
            raise RangeError("empty item", start)
        item_pos = pos
        if "-" in stripped:
            low_s, _, high_s = stripped.partition("-")
            if "-" in high_s or not low_s or not high_s:
                raise RangeError(f"malformed range {stripped!r}", item_pos)
            if not low_s.isdigit() or not high_s.isdigit():
                raise RangeError(f"malformed range {stripped!r}", item_pos)
            low, high = int(low_s), int(high_s)
            if low <= 0 or high <= 0:
                raise RangeError(f"page numbers must be positive in {stripped!r}", item_pos)
            if low > high:
                raise RangeError(f"reversed range {stripped!r}", item_pos)
            pages.update(range(low, high + 1))
        else:
            pages.add(_parse_int(stripped, item_pos))
    return sorted(pages)


def unparse(pages):
    """Format a sorted list of ints as the minimal canonical string."""
    if not pages:
        return ""
    runs = []
    start = prev = pages[0]
    for n in pages[1:]:
        if n == prev + 1:
            prev = n
            continue
        runs.append((start, prev))
        start = prev = n
    runs.append((start, prev))
    parts = [str(a) if a == b else f"{a}-{b}" for a, b in runs]
    return ",".join(parts)

