"""Parse and format page-range strings like "1-5,8,11-13"."""


class RangeError(ValueError):
    def __init__(self, message, pos):
        self.pos = pos
        super().__init__(f"{message} (at character position {pos})")


def parse(s):
    """Parse a page-range string into a sorted list of unique positive ints.

    Accepts single pages ("8") and ranges ("11-13"), separated by commas,
    with optional whitespace around each item. Overlapping/duplicate
    items are merged. Raises RangeError (with .pos) on bad input.
    """
    pages = set()
    pos = 0
    for item in s.split(","):
        # offset of first non-space char of this item within s
        lead = len(item) - len(item.lstrip())
        start = pos + lead
        stripped = item.strip()
        if not stripped:
            raise RangeError("empty item", pos)
        try:
            low_s, dash, high_s = stripped.partition("-")
            if dash:
                if "-" in high_s or not low_s or not high_s:
                    raise RangeError(f"malformed range {stripped!r}")
                low, high = int(low_s), int(high_s)
                if low <= 0 or high <= 0:
                    raise RangeError(
                        f"page numbers must be positive in {stripped!r}"
                    )
                if low > high:
                    raise RangeError(f"reversed range {stripped!r}")
            else:
                _parse_single(stripped)
                low = high = int(stripped)
        except RangeError as e:
            e.args = (f"{e.args[0]} (at character position {start})",)
            e.pos = start
            raise
        pages.update(range(low, high + 1))
        pos += len(item) + 1  # +1 for the comma
    return sorted(pages)


def _parse_single(tok):
    if not tok.isdigit() or int(tok) <= 0:
        raise RangeError(f"invalid page number {tok!r}")


def unparse(pages):
    """Format a sorted iterable of ints as the minimal canonical string."""
    pages = sorted(pages)
    if not pages:
        return ""
    runs = []
    start = prev = pages[0]
    for n in pages[1:]:
        if n == prev + 1:
            prev = n
            continue
        runs.append((start, prev))
        start = prev = n
    runs.append((start, prev))
    return ",".join(str(a) if a == b else f"{a}-{b}" for a, b in runs)

